@extends('layouts.app') @section('content')<div class="heading"><div><small>INVENTORY CONTROL / 01</small><h1>Bonjour, voici votre stock.</h1><p>Une vue fiable de vos produits, mouvements et alertes.</p></div><a class="btn" href="{{route('exports.products')}}">Exporter CSV ↓</a></div><div class="stats"><div><small>Produits suivis</small><b>{{$stats['products']}}</b></div><div class="warning"><small>Alertes de stock bas</small><b>{{$stats['low']}}</b></div><div><small>Valeur du stock</small><b>{{number_format($stats['value'],2,',',' ')}} €</b></div><div><small>Commandes actives</small><b>{{$stats['orders']}}</b></div></div><div class="grid"><section class="card"><div class="cardhead"><h2>Produits récents</h2><a href="{{route('products.index')}}">Voir tout →</a></div><table><tr><th>Produit</th><th>SKU</th><th>Stock</th><th>Seuil</th></tr>@foreach($products as $p)<tr><td><b>{{$p->name}}</b><small>{{$p->supplier?->name ?? 'Sans fournisseur'}}</small></td><td>{{$p->sku}}</td><td class="{{ $p->isLowStock()?'low':'' }}">{{$p->quantity}}</td><td>{{$p->minimum_stock}}</td></tr>@endforeach</table></section><section class="card"><div class="cardhead"><h2>Derniers mouvements</h2><a href="{{route('movements.create')}}">Ajouter →</a></div>@foreach($movements as $m)<div class="movement"><span class="dot {{$m->type}}">{{$m->type==='in'?'+':'−'}}</span><div><b>{{$m->product->name}}</b><small>{{$m->reason ?? 'Mouvement manuel'}} · {{$m->created_at->diffForHumans()}}</small></div><strong class="{{$m->type}}">{{$m->type==='in'?'+':'−'}}{{$m->quantity}}</strong></div>@endforeach</section></div>@endsection
